'use strict';
const STORAGE='kotoba-ch12-v1';
const CONTENT_REVISION='no-fictional-names-v1';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clean=s=>String(s??'').normalize('NFKC').replace(/[\s。．.、,，？！?!～~…・「」『』\[\]（）()]/g,'').trim();
const hasKanji=w=>/\p{Script=Han}/u.test(w?.c||'');
const gradeWord=(w,b,c,allowBlankKanji=false)=>{const bOk=clean(b)===clean(w.kana),writtenC=String(c??'').normalize('NFKC').trim();const cOk=w.c==='X'?(/^[xX×]$/.test(writtenC)||(allowBlankKanji&&writtenC==='')):clean(c)===clean(w.c);return{bOk,cOk,score:(Number(bOk)+Number(cOk))*.5};};
const shuffle=a=>{const out=[...a];for(let i=out.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[out[i],out[j]]=[out[j],out[i]];}return out;};
function shuffledTokens(s){let ids=shuffle(s.tokens.map((_,i)=>i));if(ids.map(i=>s.tokens[i]).join('')===s.tokens.join(''))ids.push(ids.shift());return ids;}
const wordBy=id=>WORDS.find(w=>w.id===id);const sentenceBy=id=>SENTENCES.find(s=>s.id===id);const patternBy=id=>PATTERNS.find(p=>p.id===id);
function gradeSentence(s,chosen){const answer=chosen.map(i=>s.tokens[i]).join('');if(chosen.length!==s.tokens.length)return false;if(answer===s.tokens.join(''))return true;if(s.pattern==='p12'){const alternate=[...s.tokens];[alternate[2],alternate[5]]=[alternate[5],alternate[2]];return answer===alternate.join('');}return false;}
let saved={};try{saved=JSON.parse(localStorage.getItem(STORAGE)||'{}');}catch{}
const progress=saved.progress||{words:{},sentences:{},matches:{},best:null};progress.words||={};progress.sentences||={};progress.matches||={};progress.hiraganaMatches||={};progress.activities||={};progress.kanjiWriting||={};progress.vocabularyRebuild||={};
const activeWordIds=new Set(WORDS.map(w=>w.id));for(const type of ['words','matches','hiraganaMatches','kanjiWriting','vocabularyRebuild'])for(const id of Object.keys(progress[type]))if(!activeWordIds.has(id))delete progress[type][id];
let mock=saved.contentRevision===CONTENT_REVISION?saved.mock||null:null;if(mock&&(!mock.a?.every(x=>wordBy(x.id))||!mock.b?.every(x=>sentenceBy(x.id))))mock=null;
const state={language:saved.language==='en'?'en':'zh-Hant',activity:null,dialogueCategory:'introductions',view:'home',writeMenu:'main',writeSet:null,vocabularyMenu:'main',vocabularySet:null,vocabularyContentKey:'all',handwritingMenu:'main',handwritingSet:null,filter:{ch:'all',group:'all',status:'all',kana:'all'},pattern:'all',round:null,search:'',modal:false,confirmReset:false};
const pageHistory=[];
function rememberPage(){const {view,writeMenu,vocabularyMenu,writeSet,vocabularySet,filter,pattern,search,round,activity,dialogueCategory,vocabularyContentKey,handwritingMenu,handwritingSet}=state;pageHistory.push({view,writeMenu,vocabularyMenu,writeSet,vocabularySet,filter:{...filter},pattern,search,round,activity,dialogueCategory,vocabularyContentKey,handwritingMenu,handwritingSet});}
function previousPage(fallback='home'){
  const previous=pageHistory.pop();
  if(previous){Object.assign(state,previous,{modal:false});render();window.scrollTo({top:0,behavior:'smooth'});}
  else navigate(fallback,false);
}
function breadcrumbItems(){
  const items=[{label:'Kotoba',view:'home'}],view=state.view;
  const add=(label,view,extra={})=>items.push({label,view,...extra});
  if(view==='home')return items;
  if(['dialogue','dialogue-content','demonstratives-content','activity'].includes(view)){
    add('Dialogue','dialogue');
    if(view==='activity')add(isActivityRebuild(state.activity)?'Rebuild':'Matching');
    return items;
  }
  if(view==='sentences'){add('Sentence Rebuild');return items;}
  if(['vocabulary-menu','vocabulary-content','write-menu','write','vocabulary-rebuild'].includes(view)){
    add('Vocabulary','vocabulary-menu');
    if(['write','vocabulary-rebuild'].includes(view))add(view==='write'?'Recall':'Rebuild');
    return items;
  }
  if(['handwriting-menu','kanji-writing'].includes(view))add('Kanji Writing','handwriting-menu');
  else{add(view==='mock'?'Mock quiz':'All words');return items;}
  const mode=view.startsWith('vocabulary')?'vocabulary-rebuild':view==='kanji-writing'||view==='handwriting-menu'?'kanji-writing':'write';
  const prefix=wordModePrefix(mode),menu=`${prefix}-menu`,section=state[`${prefix}Menu`];
  if(section&&section!=='main')add(section==='chapter'?'By chapter':'By category',menu,{section});
  if(!view.endsWith('-menu'))add(selectedWordSet(mode)?.label||'Practice');
  return items;
}
function breadcrumbs(){
  const items=breadcrumbItems();
  return `<nav class="breadcrumbs" aria-label="Breadcrumb"><ol>${items.map((item,index)=>`<li>${index===items.length-1?`<span aria-current="page">${esc(item.label)}</span>`:`<button data-crumb-view="${item.view}" ${item.section?`data-crumb-section="${item.section}"`:''} ${item.category?`data-crumb-category="${item.category}"`:''} ${item.key?`data-crumb-key="${item.key}"`:''}>${esc(item.label)}</button>`}</li>`).join('')}</ol></nav>`;
}
function navigateBreadcrumb(data){
  if(data.crumbKey){openVocabularyContent(data.crumbKey);return;}
  if(data.crumbCategory){openDialogueCategory(data.crumbCategory);return;}
  rememberPage();state.view=data.crumbView;state.round=null;state.modal=false;
  if(['vocabulary-menu','write-menu','handwriting-menu'].includes(state.view))state[`${state.view.slice(0,-5)}Menu`]=data.crumbSection||'main';
  render();window.scrollTo({top:0,behavior:'smooth'});
}
function wordModePrefix(mode){return mode==='vocabulary-rebuild'?'vocabulary':mode==='kanji-writing'?'handwriting':'write';}
function openWordMenu(prefix,section){rememberPage();state[`${prefix}Menu`]=section;render();window.scrollTo({top:0,behavior:'smooth'});}

function save(){try{localStorage.setItem(STORAGE,JSON.stringify({progress,mock,contentRevision:CONTENT_REVISION,language:state.language}));}catch{toast('Progress could not be saved in this browser. You can still practise.');}}
function record(type,id,ok){const p=progress[type][id]||{wins:0,attempts:0,misses:0};p.attempts++;p.wins=ok?p.wins+1:0;if(!ok)p.misses++;p.last=ok;progress[type][id]=p;save();}
function status(id,type='words'){const p=progress[type][id];return !p?'New':p.wins>=2?'Secure':p.last?'Recalled':'Review';}
function secure(type){return Object.values(progress[type]).filter(p=>p.wins>=2).length;}
function toast(message){const t=$('#toast');t.textContent=translateText(message);t.style.display='block';clearTimeout(toast.t);toast.t=setTimeout(()=>t.style.display='none',3500);}
