const icon=k=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${paths[k]||paths.home}</svg>`;
const button=(label,action,cls='',attrs='')=>`<button class="button ${cls}" data-action="${action}" ${attrs}>${label}</button>`;
const sourceTag=w=>`Ch. ${w.ch} · PDF p.${w.page} · ${VOCAB_CATEGORY_BY_WORD.get(w.id).label}`;
const STUDY_MODES=[
  {id:'dialogue',label:'Dialogue',symbol:'dialogue',copy:'Practise expressions, replies and question words.',detail:()=>`${DIALOGUES.length+demonstrativeWords.length} scenes`},
  {id:'vocabulary-menu',label:'Vocabulary',symbol:'bank',copy:'Explore vocabulary, then practise recall or rebuild its hiragana reading.',detail:()=>`${VOCABULARY_WORDS.length} forms`},
  {id:'sentences',label:'Sentence Rebuild',symbol:'sentences',copy:'Put the sentence tiles in order.',detail:()=>`${SENTENCES.length} sentences`},
  {id:'handwriting-menu',label:'Kanji Writing',symbol:'write',copy:'Draw the kanji, reveal the model and check your writing.',detail:()=>`${WORDS.filter(hasKanji).length} forms`},
  {id:'mock',label:'Mock quiz',symbol:'mock',copy:'10 words and 5 sentences. Use the quiz timing and marking.',detail:()=> '15 minutes · 20 marks'},
  {id:'bank',label:'All words',symbol:'bank',copy:'Browse words by category, reading or meaning.',detail:()=>`${VOCAB_CATEGORIES.length} groups`}
];
const views=[['home','Overview'],...STUDY_MODES.map(mode=>[mode.id,mode.label])];
function navigation(extraClass=''){if(extraClass==='overview-nav')return `<nav class="nav overview-nav" aria-label="Study modes">${STUDY_MODES.map(mode=>activityCard(mode.label,mode.copy,mode.detail(),`data-view="${mode.id}"`,'overview-card',mode.id==='mock'&&mock&&!mock.done?'Resume mock quiz':mode.id==='bank'?'Browse words':'Open practice',mode.symbol)).join('')}</nav>`;return `<nav class="nav ${extraClass}" aria-label="Study modes">${views.filter(([k])=>k!=='home'||state.view!=='home').map(([k,label])=>`<button data-view="${k}" class="${activityNav()===k?'active':''}" ${activityNav()===k?'aria-current="page"':''}>${icon(STUDY_MODES.find(mode=>mode.id===k)?.symbol||'home')}${label}</button>`).join('')}</nav>`;}
function shell(content){return `<div class="shell ${state.view==='home'?'home-view':['dialogue','dialogue-content','demonstratives-content','vocabulary-menu','vocabulary-content','write-menu'].includes(state.view)?'content-view':''}"><aside class="sidebar"><div class="brand-header"><button class="brand" data-view="home" aria-label="Kotoba overview"><span class="logo">K</span><span><span class="brand-title">kotoba</span><span class="brand-sub" style="display:block">Your study companion</span></span></button></div><div class="sidebar-foot"><div class="side-note"><span class="dot"></span>Chapters 1–2 only<p class="muted" style="margin-top:9px">Small steps.<br>One word at a time.</p><button class="scope-link" data-action="scope" style="margin-top:18px">Check the syllabus</button></div></div></aside><main class="main"><header class="topbar">${breadcrumbs()}<div class="brand-tools"><span id="pwa-update-slot" class="update-slot"></span><button class="language-switch" data-action="toggleLanguage" aria-label="${state.language==='zh-Hant'?'Switch to English':'切換至繁體中文'}" lang="${state.language==='zh-Hant'?'en':'zh-Hant'}">${state.language==='zh-Hant'?'English':'繁體中文'}</button></div></header>${content}<footer class="footer-line"><span>PDF pp.1 & 6 · Grammar from Chapters 1–2</span><button class="scope-link" data-action="scope">Scope & quiz rules</button></footer></main></div>${state.modal?scopeModal():''}`;}
function header(title,description,tag=''){return `<div class="page-head"><div><h1>${title}</h1><p>${description}</p></div>${tag?`<span class="pill">${tag}</span>`:''}</div>`;}
function scopeModal(){return `<div class="modal-backdrop" data-action="closeBackdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="scope-title"><div class="row between"><h2 id="scope-title">Your syllabus, kept close.</h2><button data-action="closeScope" aria-label="Close syllabus">${icon('close')}</button></div><p>Vocabulary is transcribed from PDF pages <strong>1 and 6</strong> of your textbook extract (printed pp.28–29 and 38–39). The selected vocabulary produces <strong>${WORDS.length} vocabulary forms</strong>, including polite and bracketed variants. Fictional companies, institutions and named characters are excluded at your request.</p><h3>Vocabulary · 10 marks</h3><p>Ten Chinese/English prompts. Write <strong>B: Hiragana</strong> and <strong>C: the printed kanji form, or X</strong>. Each column earns 0.5 marks. Both correct = 1 mark. For C, use only the forms supplied in the Japanese vocabulary columns; blank or alphabet-only forms use X.</p><p>The sheet labels B “Hiragana” without a loanword exception. Strict practice therefore uses hiragana readings even for words printed in katakana. The word list retains the book spelling too. CD has no kanji and uses X in C.</p><h3>Sentences · 10 marks</h3><p>Five reordering questions, 2 marks each. The 50 practice sentences cover all six 練習A patterns in each chapter, the 文型 and their question/answer variants, plus Chapter 1 introduction expressions. They are organised into 16 study groups. No Chapter 3–6 fill-in-the-blank exercises are included.</p><h3>Rebuild &amp; dialogue</h3><p>Vocabulary rebuilding, WH-word practice and both Dialogue modes use the selected vocabulary from your quiz pages.</p><h3>The 15-minute mock</h3><p>Samples 10 main-vocabulary words and 5 different sentence groups. All selected expressions and country names are available in the other study modes. The actual quiz questions are unknown. Later-chapter sample vocabulary is excluded from every practice bank.</p><p>Marks are checked by typed spelling and tile order. The real quiz also requires legible handwriting: practise writing on paper alongside the game. “Secure” means two consecutive successful recalls in that mode. Your progress stays in this browser.</p><h3>Input rules</h3><p>Japanese spelling matters: small kana, long vowels and the printed kanji. Harmless spaces, punctuation and placeholder ～ are ignored in vocabulary writing. Roman letters do not substitute for hiragana. For X, lowercase x and × are also accepted.</p>${button('Close','closeScope','primary')}</section></div>`;}
function home(){
  const secured=VOCABULARY_WORDS.filter(word=>(progress.words[word.id]?.wins||0)>=2).length,tried=Object.keys(progress.words).filter(id=>VOCABULARY_WORD_IDS.has(id)).length;
  const patternsDone=PATTERNS.filter(p=>SENTENCES.filter(s=>s.pattern===p.id).every(s=>(progress.sentences[s.id]?.wins||0)>=1)).length;
  return `<section class="overview-intro">${header('Choose your practice.','Choose a mode to practise the words and sentence patterns in Chapters 1–2.')}${navigation('overview-nav')}</section><section class="overview-progress" aria-labelledby="progress-title"><div class="section-head"><h2 id="progress-title">Your progress</h2><span class="small muted">Saved in this browser</span></div><div class="stats overview-stats"><div class="stat"><div class="stat-value">${tried}<span class="stat-total"> / ${VOCABULARY_WORDS.length}</span></div><div class="stat-label">Words practised</div><div class="overview-meter" aria-hidden="true"><span style="width:${100*tried/VOCABULARY_WORDS.length}%"></span></div><p class="stat-detail">${secured} secure · two correct answers in a row</p></div><div class="stat"><div class="stat-value">${patternsDone}<span class="stat-total"> / ${PATTERNS.length}</span></div><div class="stat-label">Sentence groups covered</div><div class="overview-meter" aria-hidden="true"><span style="width:${100*patternsDone/PATTERNS.length}%"></span></div><p class="stat-detail">All sentences in a group answered correctly</p></div><div class="stat"><div class="stat-value">${progress.best===null?'—':progress.best}<span class="stat-total"> / 20</span></div><div class="stat-label">Best mock quiz</div><p class="stat-detail">15 minutes · 10 words + 5 sentences</p></div></div></section>`;
}
function wordSetMenu(mode){
  const hiragana=mode==='vocabulary-rebuild',handwriting=mode==='kanji-writing',rebuilding=hiragana,prefix=wordModePrefix(mode),section=state[`${prefix}Menu`],words=handwriting?WORDS.filter(hasKanji):WORDS;
  const categories=VOCAB_CATEGORIES.filter(category=>words.some(w=>vocabularySection(w)===category.id));
  const action=rebuilding?'Start rebuilding':handwriting?'Start drawing':'Start recall',back='';
  if(section==='chapter')return header('Choose a chapter.',hiragana?'Rebuild vocabulary readings from one chapter.':handwriting?'Draw the kanji from one chapter.':'Recall vocabulary from one chapter.')+back+`<section class="mode-grid two-modes">${[1,2].map(ch=>activityCard(`Chapter ${ch} · p.${ch===1?1:6}`,hiragana?'Rebuild vocabulary readings from this chapter.':handwriting?'Draw the kanji from this chapter.':'Recall the words from this chapter.',`${words.filter(w=>w.ch===ch).length} forms`,`data-${prefix}-set="chapter-${ch}"`,'',action,'chapters')).join('')}</section>`;
  if(section==='category')return header('Choose a category.',hiragana?'Rebuild vocabulary readings from one group.':handwriting?'Draw the kanji from one group.':'Recall vocabulary from one group.')+back+`<section class="mode-grid category-grid">${categories.map(category=>activityCard(category.label,category.description,`${words.filter(w=>vocabularySection(w)===category.id).length} forms`,`data-${prefix}-set="category-${category.id}"`,'',action,category.id)).join('')}</section>`;
  return header(hiragana?'Choose vocabulary to rebuild.':handwriting?'Choose kanji to practise.':'Choose vocabulary to recall.',hiragana?'Rebuild hiragana readings, or focus on one chapter or category.':handwriting?'Practise handwriting with all kanji words, one chapter or one category.':'Practise every word, or focus on one chapter or category.')+`<section class="mode-grid">${activityCard('All words',hiragana?'Rebuild the hiragana reading for every vocabulary form.':handwriting?'Draw all taught kanji forms from pages 1 and 6.':'Recall every vocabulary form from pages 1 and 6.',`${words.length} forms`,`data-${prefix}-set="all"`,'',action,'bank')}${activityCard('By chapter','Choose Chapter 1 or Chapter 2.','2 chapters',`data-${prefix}-menu="chapter"`,'mode-yellow','Choose chapter','chapters')}${activityCard('By category','Choose a word group.',`${categories.length} groups`,`data-${prefix}-menu="category"`,'mode-blue','Choose category','categories')}</section>`;
}
function writeMenu(){return vocabularyMenu();}
function handwritingMenu(){return wordSetMenu('kanji-writing');}
function selectedWordSet(mode){return ['write','vocabulary-rebuild','kanji-writing'].includes(mode)?state[`${wordModePrefix(mode)}Set`]:null;}
function startWordPractice(mode,ids,label,key=null){if(!['write','vocabulary-rebuild','kanji-writing'].includes(mode))return;const allowed=ids.filter(id=>!!wordBy(id)&&(mode==='kanji-writing'?hasKanji(wordBy(id)):VOCABULARY_WORD_IDS.has(id)));rememberPage();state[`${wordModePrefix(mode)}Set`]={ids:allowed,label,key};if(mode!=='kanji-writing'&&key&&vocabularyStudySet(key))state.vocabularyContentKey=key;state.view=mode;begin(mode,shuffle(allowed));render();window.scrollTo({top:0,behavior:'smooth'});}
function startWriteWords(ids,label){startWordPractice('write',ids,label);}
function startWordSet(mode,key){if(!['write','vocabulary-rebuild','kanji-writing'].includes(mode))return;let words=mode==='kanji-writing'?WORDS.filter(hasKanji):VOCABULARY_WORDS,label;if(key==='all')label='All words';else if(/^chapter-[12]$/.test(key)){const ch=Number(key.slice(-1));words=words.filter(w=>w.ch===ch);label=`Chapter ${ch} · p.${ch===1?1:6}`;}else{const id=key.startsWith('category-')?key.slice(9):'',category=VOCAB_CATEGORIES.find(c=>c.id===id);if(!category)return;words=words.filter(w=>vocabularySection(w)===id);label=category.label;}if(words.length)startWordPractice(mode,words.map(w=>w.id),label,key);}
function startWriteSet(key){startWordSet('write',key);}
function options(values,selected){return values.map(([v,t])=>`<option value="${v}" ${selected===v?'selected':''}>${t}</option>`).join('');}
function filters(sentence=false,hideKana=false){return `<div class="filters"><select class="filter" data-filter="ch" aria-label="Chapter">${options([['all','Both chapters'],['1','Chapter 1 · p.1'],['2','Chapter 2 · p.6']],state.filter.ch)}</select>${sentence?`<select class="filter" data-pattern aria-label="Sentence pattern">${options([['all','All 16 sentence groups'],...PATTERNS.map(p=>[p.id,`Ch.${p.ch} · ${p.title}`])],state.pattern)}</select>`:`<select class="filter" data-filter="group" aria-label="Word category">${options([['all','All categories'],...VOCAB_CATEGORIES.map(category=>[category.id,category.label])],state.filter.group)}</select>`}<select class="filter" data-filter="status" aria-label="Practice selection">${options([['all','All items'],['review','Needs practice'],['new','Not tried yet']],state.filter.status)}</select>${!sentence&&!hideKana?`<select class="filter" data-filter="kana" aria-label="First hiragana">${options([['all','Any first hiragana'],...HIRAGANA_KEYS.filter(([k])=>WORDS.some(w=>hiraganaInitial(w)===k)).map(([k,r])=>[k,`${k} · ${r}`])],state.filter.kana||'all')}</select>`:''}</div>`;}
function pool(mode,ignoreKana=false){const sentence=mode==='sentences';return(sentence?SENTENCES:['write','vocabulary-rebuild'].includes(mode)?VOCABULARY_WORDS:WORDS).filter(x=>{if(mode==='kanji-writing'&&!hasKanji(x))return false;if(state.filter.ch!=='all'&&x.ch!==Number(state.filter.ch))return false;if(sentence&&state.pattern!=='all'&&x.pattern!==state.pattern)return false;if(!sentence&&state.filter.group!=='all'&&vocabularySection(x)!==state.filter.group)return false;if(!sentence&&!ignoreKana&&state.filter.kana&&state.filter.kana!=='all'&&hiraganaInitial(x)!==state.filter.kana)return false;const p=progress[sentence?'sentences':mode==='vocabulary-rebuild'?'vocabularyRebuild':mode==='kanji-writing'?'kanjiWriting':'words'][x.id];if(state.filter.status==='review')return !p||p.wins<2;if(state.filter.status==='new')return !p;return true;});}
function begin(mode,ids){if(!['write','vocabulary-rebuild','kanji-writing','sentences'].includes(mode))return;const items=(ids||shuffle(pool(mode).map(x=>x.id))).filter(id=>mode==='kanji-writing'?hasKanji(wordBy(id)):!['write','vocabulary-rebuild'].includes(mode)||VOCABULARY_WORD_IDS.has(id));state.round={mode,ids:items,index:0,correct:0,missed:[],revealed:false,checked:false,assisted:false,result:null,order:null,chosen:[],options:null,selected:null,b:'',c:'',hint:false};prepareQuestion();}
function prepareQuestion(){const r=state.round;if(!r||r.index>=r.ids.length)return;r.revealed=false;r.checked=false;r.assisted=false;r.result=null;r.chosen=[];r.options=null;r.selected=null;r.b='';r.c='';r.hint=false;r.ink=[];if(r.mode==='sentences')r.order=shuffledTokens(sentenceBy(r.ids[r.index]));if(r.mode==='vocabulary-rebuild')r.tileBank=vocabularyTileBank(wordBy(r.ids[r.index]));}
function current(){return state.round?.ids[state.round.index];}
function roundBar(r=state.round){return `<div class="round-info"><span>ROUND ${r.index+1} / ${r.ids.length}</span><span>${r.correct} correct so far</span></div><div class="progress-bar"><div class="progress-fill" style="width:${100*r.index/r.ids.length}%"></div></div>`;}
function completeRound(ok){const r=state.round;if(ok)r.correct++;else if(!r.missed.includes(current()))r.missed.push(current());r.checked=true;}
function nextQuestion(){state.round.index++;prepareQuestion();render();}
function roundEnd(){const r=state.round;return `<div class="study-wrap paper result-center"><div class="eyebrow muted">Round complete</div><h2 style="margin:15px 0">${r.missed.length?'Good practice. Let’s keep it going.':'A lovely clean sweep.'}</h2><div class="result-score" style="margin:24px 0">${r.correct}<small> / ${r.ids.length}</small></div><p class="muted">${r.missed.length?`${r.missed.length} items are ready for another look.`:'Another successful recall will help these words stick.'}</p><div class="card-actions">${r.missed.length?button('Practise missed items','repeatMissed','coral'):''}${button('Start a new round','restart','primary')}</div></div>`;}
function noItems(){return `<div class="empty paper"><h2>Nothing in this selection.</h2><p class="muted">Try another chapter or reset the filters.</p><div class="card-actions">${button('Show all items','resetFilters','primary')}</div></div>`;}
function practice(mode){
  if(!state.round||state.round.mode!==mode)begin(mode);
  const r=state.round,isWords=['write','vocabulary-rebuild','kanji-writing'].includes(mode),menu=`${wordModePrefix(mode)}-menu`;
  const meta={write:['Make it stick.','Chinese / English → B: Hiragana + C: printed kanji or X. Each answer is worth 0.5 marks.',selectedWordSet(mode)?.label||'Vocabulary Recall'],'kanji-writing':['Kanji Writing','Draw each kanji with a mouse, touch or pen. Reveal the model to check your attempt.',selectedWordSet(mode)?.label||'Kanji Writing'],'vocabulary-rebuild':['Vocabulary Rebuild','Build the hiragana reading using the correct tiles.',selectedWordSet(mode)?.label||'Vocabulary Rebuild'],sentences:['Piece it together.','Tap every tile in order, including punctuation. Tap a placed tile to return it to the bank.','Sentence rebuilding']}[mode];
  let html=header(...meta)+(isWords?'':filters(true));
  if(!r.ids.length)return html+noItems();
  if(r.index>=r.ids.length)return html+roundEnd();
  html+=`<section class="study-wrap">${roundBar()}${mode==='write'?writeCard():mode==='kanji-writing'?kanjiWritingCard():mode==='vocabulary-rebuild'?vocabularyRebuildCard():sentenceCard()}</section>`;
  if(mode==='sentences')html+=patternReference();return html;
}
function writeCard(){const w=wordBy(current()),r=state.round;return `<div class="paper">${vocabularyVisual(w)}<div class="eyebrow muted">${sourceTag(w)}</div><div class="write-prompt" style="margin-top:20px">${esc(w.zh)}</div><p class="muted">${esc(w.en)}</p>${w.note&&['1-c2','1-c6','1-06'].includes(w.id)?`<p class="small muted" style="margin-top:12px">${esc(w.note)}</p>`:''}<div class="answer-grid"><div><label class="field-label" for="answer-b">B · HIRAGANA <span class="muted">0.5 mark</span></label><input id="answer-b" class="input jp ${r.checked?(r.result.bOk?'correct':'wrong'):''}" lang="ja" autocomplete="off" autocapitalize="off" spellcheck="false" value="${esc(r.b)}" ${r.checked?'disabled':''} placeholder="Type hiragana" data-answer="b">${r.checked?`<div class="answer-result ${r.result.bOk?'correct-text':'wrong-text'}">${r.result.bOk?'✓ 0.5 mark':'0 marks · Correct:'} <span class="jp">${esc(w.kana)}</span></div>`:''}</div><div><label class="field-label" for="answer-c">C · KANJI / X <span class="muted">0.5 mark</span></label><input id="answer-c" class="input jp ${r.checked?(r.result.cOk?'correct':'wrong'):''}" lang="ja" autocomplete="off" autocapitalize="off" spellcheck="false" value="${esc(r.c)}" ${r.checked?'disabled':''} placeholder="Kanji, X or blank" data-answer="c">${r.checked?`<div class="answer-result ${r.result.cOk?'correct-text':'wrong-text'}">${r.result.cOk?'✓ 0.5 mark':'0 marks · Correct:'} <span class="jp">${w.c==='X'?'Blank or X':esc(w.c)}</span></div>`:''}</div></div><p class="small muted" style="margin-top:12px">No kanji? Leave C blank or enter X.</p>${r.checked?`<div class="feedback ${r.result.score===1?'':'bad'}"><strong>${r.result.score} / 1 mark</strong><p>${r.result.score===1?'Both columns are correct.':r.result.score===.5?'One column is correct. The sheet awards half a mark.':'Read the two answers, then try this word again at the end of the round.'}</p>${w.jp!==w.kana?`<p>Book spelling: <span class="jp">${esc(w.jp)}</span>. B follows the sheet’s hiragana instruction.</p>`:''}${w.note?`<p>${esc(w.note)}</p>`:''}</div>`:''}<div class="card-actions">${r.checked?button('Next word '+icon('arrow'),'next','primary'):button('Check both answers','checkWrite','primary')}</div><p class="small muted" style="text-align:center;margin-top:15px">Use your Japanese keyboard. Enter checks both answers.</p></div>`;}
function tiles(s,order,chosen,locked=false,mockIndex=null){const attrs=mockIndex===null?'':`data-mock-index="${mockIndex}"`;return `<div class="token-area ${chosen.length?'filled':''}" aria-label="Your sentence">${chosen.length?chosen.map((id,i)=>`<button class="tile jp" lang="ja" data-return="${i}" ${attrs} ${locked?'disabled':''} aria-label="Return ${esc(s.tokens[id])} to word bank">${esc(s.tokens[id])}</button>`).join(''):'<span class="empty-hint">Your sentence goes here. Tap a tile below.</span>'}</div><div class="token-bank" aria-label="Shuffled word bank">${order.map(id=>`<button class="tile jp" lang="ja" data-tile="${id}" ${attrs} ${locked||chosen.includes(id)?'disabled':''}>${esc(s.tokens[id])}</button>`).join('')}</div>`;}
function sentenceCard(){const r=state.round,s=sentenceBy(current()),p=patternBy(s.pattern);return `<div class="paper"><div class="row between"><span class="eyebrow muted">CHAPTER ${s.ch} · SENTENCE REBUILD</span><span class="chip">${status(s.id,'sentences')}</span></div><div class="sentence-prompt">${esc(s.prompt)}</div>${tiles(s,r.order,r.chosen,r.checked)}${r.hint?`<div class="hint"><strong>${esc(p.title)}</strong><div class="jp">${esc(p.formula)}</div><p>${esc(p.tip)}</p></div>`:''}${r.checked?`<div class="feedback ${r.result?'':'bad'}"><strong>${r.result?(r.assisted?'Correct with help — try it unaided next time.':'That’s the right order. +2 / 2'):r.revealed?'Study the order, then try again later.':'Not quite — look at this order.'}</strong><div class="jp" lang="ja">${esc(s.tokens.join(''))}</div><p>${esc(p.tip)}</p><p class="small">${esc(p.source)}${s.note?' · '+esc(s.note):''}</p></div>`:''}<div class="card-actions">${r.checked?button('Next sentence '+icon('arrow'),'next','primary'):button('Clear','clearTiles','ghost')+button('Pattern hint','hint','ghost')+button('Check order','checkSentence','primary',r.chosen.length!==s.tokens.length?'disabled':'')}</div>${!r.checked?`<div style="text-align:center;margin-top:14px"><button class="scope-link" data-action="revealSentence">Show answer & mark for review</button></div>`:''}</div>`;}
function patternReference(){return `<details class="details"><summary>All 16 study groups · grammar reference</summary><p>All six 練習A patterns in each chapter, grouped with the question and answer variants taught on the supplied pages. The labels below are revision aids.</p><div class="pattern-list">${PATTERNS.map(p=>`<button class="pattern-card mode-card" data-start-pattern="${p.id}"><span class="activity-icon">${icon('sentences')}</span><span class="card-copy"><span class="eyebrow muted">CH.${p.ch} · ${SENTENCES.filter(s=>s.pattern===p.id).length} PUZZLES</span><h3 style="margin-top:8px">${esc(p.title)}</h3><div class="jp">${esc(p.formula)}</div><p>${esc(p.tip)}</p><p style="margin-top:8px;font-size:10px">${esc(p.source)}</p></span><span class="card-arrow" aria-hidden="true">${icon('arrow')}</span></button>`).join('')}</div></details>`;}
function bankWordRow(w){return `<tr data-word-id="${w.id}"><td><strong>${esc(w.zh)}</strong><div class="muted">${esc(w.en)}</div><div class="muted" style="margin-top:6px">Ch.${w.ch} · PDF p.${w.page}</div></td><td><span class="jp" lang="ja">${esc(w.kana)}</span>${w.jp!==w.kana?`<div class="muted">Book: <span class="jp" style="font-size:13px">${esc(w.jp)}</span></div>`:''}</td><td>${hasKanji(w)?`<span class="jp" lang="ja">${esc(w.c)}</span>${w.note?`<div class="muted" style="max-width:250px;margin-top:6px">${esc(w.note)}</div>`:''}`:''}</td><td><span class="status-badge ${status(w.id)==='Secure'?'learned':''}">${status(w.id)}</span></td></tr>`;}
function bankRows(){const term=state.search.toLowerCase();const words=pool('bank').filter(w=>[w.zh,w.en,w.jp,w.kana,w.c].some(s=>s.toLowerCase().includes(term)));const groups=VOCAB_CATEGORIES.map(category=>{const entries=words.filter(w=>vocabularySection(w)===category.id);return entries.length?`<tbody data-word-category="${category.id}"><tr class="word-category-row"><th colspan="4" scope="rowgroup"><div class="row between"><span>${esc(category.label)}</span><span class="category-count">${entries.length} forms</span></div></th></tr>${entries.map(bankWordRow).join('')}</tbody>`:'';}).join('');return `<div class="small muted" style="margin:15px 0">${words.length} forms · a polite or bracketed alternative gets its own entry</div><div class="table-wrap"><table class="word-table"><thead><tr><th>A · Meaning</th><th>B · Hiragana</th><th>Kanji</th><th>Practice progress</th></tr></thead>${groups||'<tbody><tr><td colspan="4">No words match this search.</td></tr></tbody>'}</table></div>`;}
function bank(){return header('Every word, in one place.','Browse words by meaning and use. Kanji follow the supplied textbook pages.',`${WORDS.length} forms`)+filters()+`<div class="bank-top"><input class="input search" type="search" aria-label="Search words" data-search placeholder="Search a meaning, reading or kanji…" value="${esc(state.search)}">${button('Recall this selection','writeSelection','primary')}</div><div id="bank-rows">${bankRows()}</div>`;}
function writeSelection(){const term=state.search.toLowerCase(),ids=pool('write').filter(w=>[w.zh,w.en,w.jp,w.kana,w.c].some(s=>s.toLowerCase().includes(term))).map(w=>w.id);startWriteWords(ids,'Selected words');}
function mockIntro(){return header('Your quiz rehearsal.','A fresh set of questions, with the exact timing and marks from your information sheet.','15 minutes')+`<section class="study-wrap paper"><div class="eyebrow muted">CHAPTERS 1–2 · 20 MARKS</div><h2 style="margin:18px 0 10px">Take a breath. You know the format.</h2><p class="muted" style="font-size:13px">Work through both parts. You can revisit your answers until you submit or the timer reaches zero.</p><div class="result-breakdown"><div class="score-card"><strong>10 questions</strong><div class="small">Vocabulary · 10 marks</div><p class="small muted" style="margin-top:10px">Write hiragana + kanji / X.<br>0.5 marks for each column.</p></div><div class="score-card"><strong>5 questions</strong><div class="small">Sentences · 10 marks</div><p class="small muted" style="margin-top:10px">Reorder the word tiles.<br>2 marks per correct sentence.</p></div></div><div class="info-box" style="margin-top:22px">Samples the 62 main-vocabulary forms and five different sentence groups. No hints or corrections until submission. Expressions and country names are covered in the other modes.</div><p class="small muted">For handwriting practice, write your answers on paper too. The sheet gives no marks for illegible handwriting.</p><div class="card-actions">${button('Start 15-minute mock '+icon('arrow'),'startMock','coral')}</div></section>`;}
function startMock(){const a=shuffle([1,2].flatMap(ch=>shuffle(WORDS.filter(w=>w.group==='core'&&w.ch===ch)).slice(0,5))).map(w=>({id:w.id,b:'',c:''}));const groups=shuffle([...shuffle(PATTERNS.filter(p=>p.ch===1)).slice(0,2),...shuffle(PATTERNS.filter(p=>p.ch===2)).slice(0,3)]);const b=groups.map(p=>{const s=shuffle(SENTENCES.filter(x=>x.pattern===p.id))[0];return{id:s.id,order:shuffledTokens(s),chosen:[]};});const started=Date.now();mock={a,b,deadline:started+15*60*1000,started,done:false,tab:'a',confirm:false};save();render();}
function timeLeft(){return Math.max(0,Math.ceil((mock.deadline-Date.now())/1000));}
function formatTime(n){return `${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;}
function mockQuiz(){if(!mock)return mockIntro();if(mock.done)return mockResult();const aDone=mock.a.filter(x=>x.b.trim()&&x.c.trim()).length,bDone=mock.b.filter(x=>x.chosen.length===sentenceBy(x.id).tokens.length).length;return header('One question at a time.','Your answers are saved as you go. The timer continues if you leave or reload this page.')+`<div class="mock-top"><div class="mock-tabs"><button data-mock-tab="a" class="${mock.tab==='a'?'active':''}">Vocabulary · ${aDone}/10</button><button data-mock-tab="b" class="${mock.tab==='b'?'active':''}">Sentences · ${bDone}/5</button></div><div style="text-align:right"><div class="timer ${timeLeft()<60?'warn':''}" role="timer" aria-label="Time remaining">${formatTime(timeLeft())}</div><div class="small muted">TIME REMAINING</div></div></div><div class="study-wrap">${mock.tab==='a'?`<p class="small muted">B: hiragana. C: printed kanji / X. 0.5 marks for each column.</p>${mock.a.map((q,i)=>{const w=wordBy(q.id);return `<section class="mock-question"><div class="mock-q-title">${i+1}. ${esc(w.zh)}</div><div class="small muted">${esc(w.en)}</div><div class="answer-grid"><div><label class="field-label" for="mock-b-${i}">B · HIRAGANA</label><input class="input jp" id="mock-b-${i}" data-mock-field="b" data-mock-index="${i}" value="${esc(q.b)}" lang="ja" autocomplete="off" autocapitalize="off" spellcheck="false"></div><div><label class="field-label" for="mock-c-${i}">C · KANJI / X</label><input class="input jp" id="mock-c-${i}" data-mock-field="c" data-mock-index="${i}" value="${esc(q.c)}" lang="ja" autocomplete="off" autocapitalize="off" spellcheck="false"></div></div></section>`;}).join('')}<div class="card-actions"><button class="button primary" data-mock-tab="b">Go to sentences ${icon('arrow')}</button></div>`:`<p class="small muted">Put every tile in order. 2 marks per correct sentence. Tap a placed tile to undo it.</p>${mock.b.map((q,i)=>{const s=sentenceBy(q.id);return `<section class="mock-question"><div class="eyebrow muted">QUESTION ${i+1} · 2 MARKS</div><div class="sentence-prompt">${esc(s.prompt)}</div>${tiles(s,q.order,q.chosen,false,i)}</section>`;}).join('')}`}<div style="margin-top:35px;border-top:1px solid var(--line);padding-top:22px">${mock.confirm?`<div class="info-box">You have ${10-aDone} unfinished vocabulary questions and ${5-bDone} unfinished sentences. Submit now for your score, or keep working.</div><div class="card-actions">${button('Keep working','cancelSubmit','ghost')}${button('Submit quiz now','finishMock','coral')}</div>`:`<div class="card-actions">${button('Submit both parts','confirmSubmit','coral')}</div>`}</div></div>`;}
function finishMock(timedout=false){if(!mock||mock.done)return;mock.done=true;mock.timedout=timedout;mock.finished=Date.now();mock.aResults=mock.a.map(q=>{const result=gradeWord(wordBy(q.id),q.b,q.c);record('words',q.id,result.score===1);return result;});mock.bResults=mock.b.map(q=>{const ok=gradeSentence(sentenceBy(q.id),q.chosen);record('sentences',q.id,ok);return ok;});mock.aScore=mock.aResults.reduce((n,r)=>n+r.score,0);mock.bScore=mock.bResults.filter(Boolean).length*2;mock.score=mock.aScore+mock.bScore;progress.best=Math.max(progress.best||0,mock.score);save();state.view='mock';render();window.scrollTo({top:0,behavior:'smooth'});}
function mockResult(){return header('Your practice paid off.','Review the details below, then give the missed items another go.','Mock complete')+`<div class="study-wrap"><div class="paper result-center"><div class="eyebrow muted">${mock.timedout?'TIME IS UP · ANSWERS SUBMITTED':'CHAPTERS 1–2 · YOUR RESULT'}</div><div class="result-score" style="margin:25px 0">${mock.score}<small> / 20</small></div><p class="muted">${mock.score>=18?'You’re finding your rhythm. Keep the spelling precise.':mock.score>=12?'A solid foundation. A little focused revision will help.':'Now you know exactly what to practise next.'}</p><div class="result-breakdown"><div class="score-card"><strong>${mock.aScore} / 10</strong><span class="small">Vocabulary</span></div><div class="score-card"><strong>${mock.bScore} / 10</strong><span class="small">Sentence order</span></div></div><div class="card-actions">${button('Review missed words','mockMissedWords','ghost')}${button('Review missed sentences','mockMissedSentences','ghost')}${button('New mock quiz','newMock','primary')}</div></div><details class="details" open><summary>Vocabulary · every answer</summary>${mock.a.map((q,i)=>{const w=wordBy(q.id),r=mock.aResults[i];return `<div class="result-row"><div class="row between"><strong>${i+1}. ${esc(w.zh)} · ${esc(w.en)}</strong><span class="${r.score===1?'correct-text':'wrong-text'}">${r.score} / 1</span></div><div class="small muted" style="margin-top:10px">YOUR B <span class="jp ${r.bOk?'correct-text':'wrong-text'}">${esc(q.b)||'—'}</span> · YOUR C <span class="jp ${r.cOk?'correct-text':'wrong-text'}">${esc(q.c)||'—'}</span></div><div class="jp">B: ${esc(w.kana)} · C: ${esc(w.c)}</div></div>`;}).join('')}</details><details class="details" open><summary>Sentences · every answer</summary>${mock.b.map((q,i)=>{const s=sentenceBy(q.id),ok=mock.bResults[i];return `<div class="result-row"><div class="row between"><strong>${i+1}. ${esc(s.prompt)}</strong><span class="${ok?'correct-text':'wrong-text'}">${ok?'2':'0'} / 2</span></div><div class="small muted" style="margin-top:10px">YOUR ORDER</div><div class="jp ${ok?'correct-text':'wrong-text'}">${esc(q.chosen.map(x=>s.tokens[x]).join(''))||'—'}</div><div class="small muted" style="margin-top:10px">CORRECT ORDER</div><div class="jp">${esc(s.tokens.join(''))}</div><p>${esc(patternBy(s.pattern).tip)}</p></div>`;}).join('')}</details></div>`;}
function render(){const previousNav=document.querySelector('.overview-nav')||document.querySelector('.sidebar .nav');const navScroll=previousNav?.scrollLeft||0;const page=state.view==='home'?home():state.view==='bank'?bank():state.view==='mock'?mockQuiz():state.view==='write-menu'?writeMenu():state.view==='vocabulary-menu'?vocabularyMenu():state.view==='vocabulary-content'?vocabularyContent():state.view==='handwriting-menu'?handwritingMenu():state.view==='demonstratives-content'?demonstrativesContent():state.view==='dialogue'?dialogueMenu():state.view==='dialogue-content'?dialogueContent():state.view==='activity'?activityPage():practice(state.view);$('#app').innerHTML=localizeMarkup(shell(page));const currentNav=document.querySelector('.overview-nav')||document.querySelector('.sidebar .nav');if(currentNav)currentNav.scrollLeft=navScroll;if(document.documentElement)document.documentElement.lang=state.language;if(state.modal)setTimeout(()=>$('.modal button')?.focus(),0);}
function navigate(view,remember=true){if(['write-menu','cards'].includes(view))view='vocabulary-menu';if(remember)rememberPage();state.view=view==='rebuild-menu'?'home':['matching','match','kanji-menu','hiragana-menu','hiragana-match'].includes(view)?'vocabulary-menu':view==='hiragana'?'home':view==='cards'?'write-menu':view;state.modal=false;state.round=null;if(state.view==='write-menu')state.writeMenu='main';if(state.view==='vocabulary-menu')state.vocabularyMenu='main';if(state.view==='handwriting-menu')state.handwritingMenu='main';render();window.scrollTo({top:0,behavior:'smooth'});}
function resetFilters(){state.filter={ch:'all',group:'all',status:'all',kana:'all'};state.pattern='all';state.round=null;}
function run(action){if(action.startsWith('vocabulary')){vocabularyAction(action);return;}if(action.startsWith('kanji')){kanjiWritingAction(action);return;}const r=state.round;switch(action){case'back':previousPage();break;case'toggleLanguage':state.language=state.language==='zh-Hant'?'en':'zh-Hant';save();render();break;case'writeSelection':writeSelection();break;case'scope':state.modal=true;render();break;case'closeScope':state.modal=false;render();break;case'closeBackdrop':break;case'checkWrite':if(!r.checked){r.result=gradeWord(wordBy(current()),r.b,r.c,true);record('words',current(),r.result.score===1);completeRound(r.result.score===1);render();}break;case'next':nextQuestion();break;case'restart':begin(state.view,selectedWordSet(state.view)?shuffle(selectedWordSet(state.view).ids):undefined);render();break;case'repeatMissed':begin(state.view,shuffle(r.missed));render();break;case'resetFilters':resetFilters();render();break;case'clearTiles':r.chosen=[];render();break;case'hint':r.hint=true;r.assisted=true;render();break;case'checkSentence':if(!r.checked){r.result=gradeSentence(sentenceBy(current()),r.chosen);record('sentences',current(),r.result&&!r.assisted);completeRound(r.result&&!r.assisted);render();}break;case'revealSentence':if(!r.checked){r.revealed=true;r.result=false;r.assisted=true;record('sentences',current(),false);completeRound(false);render();}break;case'startMock':startMock();break;case'newMock':mock=null;save();render();break;case'confirmSubmit':mock.confirm=true;render();break;case'cancelSubmit':mock.confirm=false;render();break;case'finishMock':finishMock();break;case'mockMissedWords':{const ids=mock.a.filter((q,i)=>mock.aResults[i].score<1).map(q=>q.id);if(!ids.length){toast('All vocabulary answers were correct.');break;}resetFilters();startWriteWords(ids,'Missed words');break;}case'mockMissedSentences':{const ids=mock.b.filter((q,i)=>!mock.bResults[i]).map(q=>q.id);if(!ids.length){toast('All sentence orders were correct.');break;}resetFilters();state.view='sentences';begin('sentences',ids);render();window.scrollTo({top:0,behavior:'smooth'});break;}}}
document.addEventListener('click',e=>{const target=e.target.closest('button,[data-action]');if(!target||target.disabled)return;if(target.dataset.crumbView){navigateBreadcrumb(target.dataset);return;}if(activityClick(target))return;if(target.dataset.vocabularyPractice){startVocabularyPractice(target.dataset.vocabularyPractice);return;}if(target.dataset.handwritingMenu){openWordMenu('handwriting',target.dataset.handwritingMenu);return;}if(target.dataset.handwritingSet){startWordSet('kanji-writing',target.dataset.handwritingSet);return;}if(target.dataset.vocabularyMenu){openWordMenu('vocabulary',target.dataset.vocabularyMenu);return;}if(target.dataset.vocabularySet){openVocabularyContent(target.dataset.vocabularySet);return;}if(target.dataset.writeMenu){openWordMenu('write',target.dataset.writeMenu);return;}if(target.dataset.writeSet){startWriteSet(target.dataset.writeSet);return;}if(target.dataset.vocabularyTile!==undefined||target.dataset.vocabularyReturn!==undefined){vocabularyTileClick(target.dataset);return;}if(target.dataset.view){navigate(target.dataset.view);return;}if(target.dataset.action){if(target.dataset.action==='closeBackdrop'){if(e.target===target){state.modal=false;render();}return;}run(target.dataset.action);return;}if(target.dataset.tile!==undefined||target.dataset.return!==undefined){const isMock=target.dataset.mockIndex!==undefined;const q=isMock?mock.b[Number(target.dataset.mockIndex)]:state.round;if((isMock&&mock.done)||(!isMock&&q.checked))return;if(target.dataset.tile!==undefined){const id=Number(target.dataset.tile);if(!q.chosen.includes(id))q.chosen.push(id);}else q.chosen.splice(Number(target.dataset.return),1);if(isMock){save();const y=window.scrollY;render();window.scrollTo(0,y);}else render();return;}if(target.dataset.startPattern){state.pattern=target.dataset.startPattern;state.filter.ch='all';state.filter.status='all';state.view='sentences';begin('sentences');render();window.scrollTo({top:0,behavior:'smooth'});return;}if(target.dataset.mockTab){mock.tab=target.dataset.mockTab;save();render();window.scrollTo({top:0,behavior:'smooth'});}});
document.addEventListener('input',e=>{const t=e.target;if(t.dataset.answer)state.round[t.dataset.answer]=t.value;if(t.dataset.mockField){mock.a[Number(t.dataset.mockIndex)][t.dataset.mockField]=t.value;save();const count=mock.a.filter(q=>q.b.trim()&&q.c.trim()).length;const tab=$('[data-mock-tab="a"]');if(tab)tab.textContent=translateText(`Vocabulary · ${count}/10`);}if(t.hasAttribute('data-search')){state.search=t.value;$('#bank-rows').innerHTML=localizeMarkup(bankRows());}});
document.addEventListener('change',e=>{const t=e.target;if(t.hasAttribute('data-vocabulary-select')){openVocabularyContent(t.value);return;}if(t.hasAttribute('data-dialogue-select')){selectDialogueCategory(t.value);return;}if(t.dataset.filter){state.filter[t.dataset.filter]=t.value;state.round=null;render();}if(t.hasAttribute('data-pattern')){state.pattern=t.value;state.filter.ch='all';state.round=null;render();}});
document.addEventListener('keydown',e=>{if(e.isComposing)return;if(e.key==='Escape'&&state.modal){run('closeScope');return;}if(state.modal&&e.key==='Tab'){const focusable=[...document.querySelectorAll('.modal button')];const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}return;}if(state.modal)return;if(state.view==='activity'&&!['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)){const a=state.activity;if(a&&a.index<a.ids.length){if(e.key==='Enter'&&!['BUTTON','A'].includes(e.target.tagName)){e.preventDefault();if(a.checked)activityAction('activityNext');else if(isActivityRebuild(a)&&a.chosen.length===kanaUnits(vocabularyReading(activityCurrent())).length)checkActivity();}else if(e.key==='Backspace'&&isActivityRebuild(a)&&!a.checked){e.preventDefault();activityAction('activityUndo');}else if(/^[1-4]$/.test(e.key)&&!a.checked&&!isActivityRebuild(a)){e.preventDefault();checkActivity(a.choices[Number(e.key)-1]?.id);}return;}}const isInput=['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName);if(isInput){if(e.key==='Enter'&&state.view==='write'&&!state.round.checked){e.preventDefault();run('checkWrite');}return;}const r=state.round;if(!r||r.index>=r.ids.length)return;if(state.view==='vocabulary-rebuild'&&!r.checked){if(e.key==='Backspace'){e.preventDefault();vocabularyAction('vocabularyUndo');}else if(e.key==='Enter'&&!['BUTTON','A'].includes(e.target.tagName)){e.preventDefault();vocabularyAction('vocabularyCheck');return;}}if(e.key==='Enter'&&r.checked&&!['BUTTON','A'].includes(e.target.tagName)){e.preventDefault();run('next');}});
setInterval(()=>{if(mock&&!mock.done){const time=timeLeft(),el=$('.timer');if(el){el.textContent=formatTime(time);el.classList.toggle('warn',time<60);}if(time===0)finishMock(true);}},1000);
render();
